mod.css:
.mcp-overlay{position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.25);display:flex;justify-content:center;align-items:flex-start;padding-top:80px}
.mcp-box{width:600px;max-width:92vw;background:#fff;color:#000;border:1px solid #e5e5e5;border-radius:8px;box-shadow:0 10px 30px rgba(0,0,0,.18);font-family:"Titillium Web",inherit;overflow:hidden}
.mcp-head{display:flex;align-items:center;gap:8px;padding:8px;border-bottom:1px solid #e5e5e5}
.mcp-input{flex:1;font:inherit;font-size:16px;padding:6px 10px;border:1px solid #d4d4d4;border-radius:6px;outline:none;background:#fbfbfb;color:inherit}
.mcp-input:focus{border-color:#e9573f;box-shadow:0 0 0 2px rgba(233,87,63,.2)}
.mcp-badge{font-size:12px;padding:2px 8px;border-radius:999px;background:#f2f2f2;color:#555;white-space:nowrap}
.mcp-list{max-height:360px;overflow-y:auto;margin:0;padding:4px 0;list-style:none}
.mcp-row{display:flex;justify-content:space-between;gap:12px;padding:6px 14px;font-size:15px;cursor:pointer}
.mcp-row small{color:#737373;font-size:12px}
.mcp-row.mcp-sel{background:#fdece8;color:#c1391f}
.mcp-empty{padding:10px 14px;color:#737373;font-size:14px}
.mcp-btn{margin-left:12px;font:inherit;font-size:13px;padding:4px 10px;border:1px solid #d4d4d4;border-radius:6px;background:transparent;color:inherit;cursor:pointer;white-space:nowrap}
.mcp-btn:hover{border-color:#e9573f;color:#e9573f}
@media (prefers-color-scheme:dark){.mcp-box{background:#000;color:#fff;border-color:#333}.mcp-head{border-color:#333}.mcp-input{background:#111;border-color:#333}.mcp-badge{background:#222;color:#bbb}.mcp-row.mcp-sel{background:#2a1510;color:#ff8a6f}}

