let overlay = null;
const clean = s => (s || "").replace(/\s+/g, " ").trim();
function gather() {
  const cmds = [], seen = new Set();
  const add = (label, hint, run) => { const k = label + "|" + hint; if (!label || seen.has(k)) return; seen.add(k); cmds.push({ label, hint, run }); };
  add("Search: Focus gem search", "Search", () => { const q = morse.$$("#query")[0]; q && q.focus(); });
  const groups = [
    ["header nav a", "Go to"], ["nav[aria-label='Breadcrumb'] a", "Breadcrumb"],
    ["nav[aria-label='Gem navigation'] a", "Gem"], ["aside[aria-label='Details'] a", "Details"],
    ["main a", "Open"], ["header div.ml-auto.flex a", "Account"]
  ];
  groups.forEach(([sel, p]) => morse.$$(sel).forEach(a => {
    const t = clean(a.getAttribute("aria-label") || a.textContent);
    if (t) add(p + ": " + t, (a.getAttribute("href") || "").slice(0, 40), () => a.click());
  }));
  morse.$$("main h3, aside h1, aside h2").forEach(h => {
    const t = clean(h.textContent);
    add("Scroll to: " + t, "Section", () => h.scrollIntoView({ behavior: "smooth", block: "start" }));
  });
  add("View: Scroll to top", "Home", () => scrollTo({ top: 0, behavior: "smooth" }));
  return cmds;
}
function close() { if (overlay) { overlay.remove(); overlay = null; } }
function open() {
  if (overlay) return;
  const cmds = gather();
  let shown = cmds, idx = 0;
  const input = morse.el("input", { class: "mcp-input", placeholder: "Type the name of a command to run.", "aria-label": "Command" });
  const badge = morse.el("span", { class: "mcp-badge" });
  const list = morse.el("ul", { class: "mcp-list", role: "listbox" });
  const run = c => { close(); c && c.run(); };
  const render = () => {
    list.textContent = "";
    badge.textContent = shown.length + " Results";
    if (!shown.length) list.append(morse.el("li", { class: "mcp-empty", text: "No matching commands" }));
    let sel = null;
    shown.forEach((c, i) => {
      const li = morse.el("li", { class: "mcp-row" + (i === idx ? " mcp-sel" : ""), role: "option",
        on: { click: () => run(c), mousemove: () => { if (idx !== i) { idx = i; render(); } } } },
        morse.el("span", { text: c.label }), morse.el("small", { text: c.hint }));
      if (i === idx) sel = li;
      list.append(li);
    });
    sel && sel.scrollIntoView({ block: "nearest" });
  };
  input.addEventListener("input", () => {
    const words = input.value.replace(/^>/, "").toLowerCase().split(/\s+/).filter(Boolean);
    shown = cmds.filter(c => words.every(w => c.label.toLowerCase().includes(w)));
    idx = 0; render();
  });
  input.addEventListener("keydown", e => {
    if (e.key === "ArrowDown") { e.preventDefault(); idx = Math.min(idx + 1, shown.length - 1); render(); }
    else if (e.key === "ArrowUp") { e.preventDefault(); idx = Math.max(idx - 1, 0); render(); }
    else if (e.key === "Enter") { e.preventDefault(); run(shown[idx]); }
    else if (e.key === "Escape") { e.preventDefault(); close(); }
  });
  const box = morse.el("div", { class: "mcp-box", role: "dialog", "aria-label": "Command palette" },
    morse.el("div", { class: "mcp-head" }, input, badge), list);
  overlay = morse.el("div", { class: "mcp-overlay", on: { mousedown: e => { if (e.target === overlay) close(); } } }, box);
  document.body.append(overlay);
  input.value = ">"; render(); input.focus();
}
morse.on(document, "keydown", e => {
  if ((e.ctrlKey || e.metaKey) && e.shiftKey && (e.key === "P" || e.key === "p")) { e.preventDefault(); overlay ? close() : open(); }
  else if (e.key === "Escape" && overlay) close();
});
morse.watch("header div.ml-auto.flex > div.ml-3.flex", el => {
  el.append(morse.el("button", { class: "mcp-btn", type: "button", title: "Command palette (Ctrl+Shift+P)", text: "⌘ Commands", on: { click: open } }));
});
